@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700;800&family=Space+Grotesk:wght@400;500;600;700&display=swap');
:root{color-scheme:dark;--ink:#f2f6ff;--muted:#91a1bd;--line:rgba(155,180,224,.13);--mint:#8debd0;--gold:#ffce83;--bg:#0e192e;--panel:#17243a}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:var(--bg);color:var(--ink);font-family:'DM Sans',sans-serif}body{background:radial-gradient(ellipse at 50% 35%,#1a2a46 0%,#101b31 60%,#0b1425 100%);-webkit-tap-highlight-color:transparent}.game-shell{height:100dvh;min-height:520px;display:flex;flex-direction:column;padding:0 36px env(safe-area-inset-bottom);max-width:1800px;margin:auto}.topbar{height:72px;flex:none;display:flex;align-items:center;border-bottom:1px solid var(--line);position:relative}.brand{display:flex;align-items:center;gap:11px;color:inherit;text-decoration:none}.brand-mark{width:37px;height:37px;display:grid;place-items:center;border:1px solid rgba(141,235,208,.3);border-radius:11px;color:var(--mint);font-size:21px;background:rgba(141,235,208,.07);box-shadow:0 0 22px rgba(141,235,208,.06)}.brand strong,.brand small{display:block;letter-spacing:.13em}.brand strong{font-family:'Space Grotesk',sans-serif;font-size:12px}.brand small{font-family:'DM Mono',monospace;font-size:9px;color:#99aac5;letter-spacing:.17em;margin-top:3px}.season-tag{position:absolute;left:50%;transform:translateX(-50%);font:10px 'DM Mono',monospace;letter-spacing:.12em;color:#a6b4cb}.live-dot,.radar-dot,.intel-dot{width:6px;height:6px;display:inline-block;border-radius:50%;background:var(--mint);box-shadow:0 0 9px var(--mint);margin-right:8px}.icon-button{margin-left:auto;width:35px;height:35px;border:1px solid var(--line);border-radius:10px;color:#aebdd4;background:rgba(255,255,255,.025);font-size:19px;cursor:pointer}.game-layout{flex:1;min-height:0;display:grid;grid-template-columns:minmax(155px,205px) minmax(0,1fr) minmax(155px,205px);gap:24px;padding:24px 0 17px}.side-panel{display:flex;flex-direction:column;min-height:0}.left-panel{padding-top:17px}.mission-label,.intel-heading{font:10px 'DM Mono',monospace;color:#9badc9;letter-spacing:.13em}.tiny-star{color:var(--gold);font-size:15px;margin-right:5px}.side-panel h1{font:600 clamp(28px,3vw,43px)/.99 'Space Grotesk',sans-serif;letter-spacing:-.06em;margin:19px 0 15px}.side-panel h1 em,.intro-card h2 em{font-style:normal;color:var(--mint)}.mission-copy{font-size:12px;line-height:1.75;color:#9babc4;max-width:195px;margin:0}.objective-card{margin-top:24px;padding:12px 11px;display:flex;align-items:center;gap:10px;background:linear-gradient(110deg,rgba(141,235,208,.09),rgba(141,235,208,.025));border:1px solid rgba(141,235,208,.13);border-radius:10px}.objective-icon{font-size:23px}.objective-card b,.objective-card small{display:block}.objective-card b{font:9px 'DM Mono',monospace;letter-spacing:.12em;color:var(--mint)}.objective-card small{font-size:10px;color:#aebbd0;margin-top:4px}.objective-card i{font-style:normal;color:var(--mint);margin-left:auto}.best-score{margin-top:auto;padding:17px 0 6px;border-top:1px solid var(--line)}.best-score span{display:block;font:9px 'DM Mono',monospace;color:#8292ae;letter-spacing:.12em}.best-score strong{display:block;font:500 27px 'Space Grotesk',sans-serif;margin-top:7px}.play-column{display:flex;flex-direction:column;min-width:0;min-height:0}.hud{display:grid;grid-template-columns:1fr .85fr 1.2fr;gap:9px;margin-bottom:12px}.hud-card{min-height:59px;background:rgba(24,38,61,.87);border:1px solid var(--line);border-radius:10px;display:flex;align-items:center;padding:8px 13px;gap:10px;box-shadow:0 5px 20px rgba(2,8,19,.1)}.hud-icon{font-size:17px;color:var(--mint)}.timer-card .hud-icon{color:var(--gold)}.hud-card small{display:block;font:9px 'DM Mono',monospace;letter-spacing:.11em;color:#8f9fb9;margin-bottom:3px}.hud-card strong{font:600 16px 'Space Grotesk',sans-serif;letter-spacing:.03em}.hud-card strong i{font-style:normal;color:#7587a3;font-size:12px}.timer-card strong{color:var(--gold);font-size:19px}.timer-card strong span{font:10px 'DM Mono',monospace;margin-left:2px}.ammo-card strong{font:11px 'DM Mono',monospace;letter-spacing:2px;color:var(--mint);white-space:nowrap}.scene-wrap{flex:1;min-height:220px;position:relative;overflow:hidden;border:1px solid rgba(158,189,228,.22);border-radius:13px;background:#1a3352;box-shadow:0 20px 55px rgba(0,0,0,.24),inset 0 0 0 5px rgba(7,14,27,.12);touch-action:none}.scene-wrap:after{content:'';position:absolute;inset:0;border:1px solid rgba(255,255,255,.08);border-radius:12px;pointer-events:none;z-index:2}canvas{width:100%;height:100%;display:block;cursor:none;touch-action:none}.scene-vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(0deg,rgba(7,18,33,.21),transparent 30%,rgba(15,27,46,.13));z-index:1}.scene-caption{position:absolute;top:14px;left:15px;z-index:3;font:9px 'DM Mono',monospace;color:#d4deed;letter-spacing:.1em;background:rgba(13,25,42,.53);border:1px solid rgba(198,218,244,.11);padding:8px 10px;border-radius:6px;backdrop-filter:blur(8px)}.scene-caption .radar-dot{width:5px;height:5px}.toast{position:absolute;z-index:4;left:50%;top:20%;transform:translate(-50%,-6px);opacity:0;pointer-events:none;font:600 11px 'DM Mono',monospace;letter-spacing:.12em;color:var(--mint);background:rgba(12,27,43,.9);border:1px solid rgba(141,235,208,.34);padding:11px 16px;border-radius:8px;transition:opacity .15s,transform .15s}.toast.show{opacity:1;transform:translate(-50%,0)}.overlay{position:absolute;inset:0;z-index:5;display:grid;place-items:center;background:rgba(8,17,31,.49);backdrop-filter:blur(5px);padding:15px}.overlay.hidden{display:none}.intro-card{max-width:330px;width:100%;text-align:center;padding:22px 24px 19px;border:1px solid rgba(174,199,233,.19);border-radius:14px;background:linear-gradient(150deg,rgba(27,43,66,.96),rgba(15,29,48,.97));box-shadow:0 18px 70px rgba(0,0,0,.35)}.intro-kicker{font:9px 'DM Mono',monospace;color:var(--gold);letter-spacing:.18em}.intro-kicker span{padding:0 5px}.intro-santa{font-size:29px;line-height:1;margin:13px auto 10px;filter:drop-shadow(0 5px 8px rgba(0,0,0,.2))}.intro-card h2{font:600 30px/.99 'Space Grotesk',sans-serif;letter-spacing:-.055em;margin:0 0 10px}.intro-card p{font-size:11px;line-height:1.65;color:#a9b8ce;max-width:260px;margin:0 auto 15px}.play-button{height:43px;width:100%;display:flex;align-items:center;justify-content:center;position:relative;border:0;border-radius:7px;background:var(--mint);color:#11263a;font:700 10px 'DM Mono',monospace;letter-spacing:.13em;cursor:pointer;transition:transform .15s,filter .15s}.play-button:hover{transform:translateY(-2px);filter:brightness(1.07)}.play-button b{position:absolute;right:14px;font-size:17px}.intro-hint{margin-top:13px;font:8px 'DM Mono',monospace;line-height:1.5;color:#7588a5;letter-spacing:.075em}.controls-bar{height:65px;flex:none;display:flex;align-items:center;gap:20px}.control-tip,.wind{display:flex;align-items:center;gap:9px}.tip-icon{width:28px;height:28px;border:1px solid rgba(141,235,208,.22);border-radius:8px;display:grid;place-items:center;color:var(--mint);font-size:18px}.control-tip b,.control-tip small,.wind b,.wind small{display:block}.control-tip b,.wind b{font:9px 'DM Mono',monospace;letter-spacing:.08em;color:#ccd6e6}.control-tip small,.wind small{font:9px 'DM Mono',monospace;color:#8293af;margin-top:4px}.wind{margin-left:auto}.wind-icon{font-size:20px;color:#94abc8}.wind-meter{display:flex;gap:3px;margin-left:3px}.wind-meter i{width:3px;height:12px;border-radius:2px;background:#34455f}.wind-meter i.active{background:var(--mint);height:16px;margin-top:-2px}.reload-button{height:35px;display:flex;align-items:center;gap:7px;padding:0 11px;margin-left:15px;border:1px solid var(--line);border-radius:7px;background:rgba(255,255,255,.025);color:#c3d0e4;font:9px 'DM Mono',monospace;letter-spacing:.07em;cursor:pointer}.reload-button span{font-size:16px;color:var(--mint)}kbd{font:8px 'DM Mono',monospace;color:#8c9cb5;padding:2px 4px;border:1px solid rgba(155,180,224,.18);border-radius:3px} .right-panel{padding-top:0;gap:12px}.weather-card,.intel-card,.tip-card{border:1px solid var(--line);border-radius:10px;background:rgba(23,36,57,.67);padding:13px}.weather-top,.weather-bottom{display:flex;justify-content:space-between;font:9px 'DM Mono',monospace;letter-spacing:.1em;color:#93a3bd}.weather-top span:last-child{font-size:14px;color:var(--mint)}.weather-main{display:flex;align-items:center;justify-content:space-between;padding:8px 0 9px}.weather-icon{font-size:30px;color:#dbe8ff}.weather-main strong{font:500 29px 'Space Grotesk',sans-serif}.weather-main strong small{font-size:11px;color:#9dadc5}.weather-bottom{font-size:8px;color:#a3b2ca}.weather-flakes{color:#8edfcf;letter-spacing:3px}.intel-card{padding:13px 12px}.intel-heading{font-size:9px;color:#a6b5cb}.intel-heading span{color:var(--mint);font-size:14px;margin-right:5px}.intel-line{display:flex;align-items:flex-start;margin:14px 0 9px}.intel-dot{margin:5px 8px 0 0;width:5px;height:5px;flex:none}.intel-line p{font-size:10px;line-height:1.55;color:#9aabc3;margin:0}.intel-line b{color:#e1e9f5;font-weight:500}.signal-bars{display:flex;align-items:end;gap:3px;height:16px}.signal-bars i{display:block;width:calc((100% - 18px)/7);height:4px;background:#34445f;border-radius:2px}.signal-bars i:nth-child(2),.signal-bars i:nth-child(3),.signal-bars i:nth-child(4){height:8px;background:#74d7c0}.signal-bars i:nth-child(5){height:13px;background:#74d7c0}.signal-bars i:nth-child(6){height:16px;background:#74d7c0}.signal-caption{display:block;font:8px 'DM Mono',monospace;color:#7588a4;letter-spacing:.12em;margin-top:7px}.tip-card{position:relative;margin-top:auto;padding:14px}.tip-card>span:first-child{font:8px 'DM Mono',monospace;color:var(--gold);letter-spacing:.12em}.tip-card p{font:italic 11px/1.6 'DM Sans',sans-serif;color:#a6b5ca;margin:8px 0 0;max-width:145px}.tip-sparkle{position:absolute;right:12px;bottom:12px;color:var(--gold);font-size:17px}footer{height:33px;flex:none;border-top:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;color:#71829f;font:8px 'DM Mono',monospace;letter-spacing:.09em}footer b{color:#9eafc9;font-weight:500}footer i{font-style:normal;margin:0 5px;color:#43536c}.footer-right b{color:var(--gold)}
@media(max-width:900px){.game-shell{padding-left:22px;padding-right:22px}.game-layout{grid-template-columns:150px minmax(0,1fr);gap:17px}.right-panel{display:none}.side-panel h1{font-size:34px}.mission-copy{font-size:11px}}
@media(max-width:600px){html,body{overflow:auto}.game-shell{height:100dvh;min-height:560px;padding:0 12px env(safe-area-inset-bottom)}.topbar{height:55px}.brand-mark{width:32px;height:32px}.brand strong{font-size:10px}.brand small{font-size:8px}.season-tag{font-size:8px;letter-spacing:.06em;white-space:nowrap;left:auto;right:46px;transform:none}.game-layout{display:flex;flex-direction:column;padding:10px 0 5px;gap:8px}.left-panel{display:none}.play-column{flex:1;min-height:0}.hud{gap:6px;margin-bottom:7px}.hud-card{min-height:51px;padding:6px 8px;gap:6px;border-radius:8px}.hud-icon{font-size:14px}.hud-card small{font-size:7px;letter-spacing:.06em}.hud-card strong{font-size:14px}.timer-card strong{font-size:16px}.hud-card strong i{font-size:10px}.ammo-card strong{font-size:8px;letter-spacing:1px}.scene-wrap{min-height:0;border-radius:10px}.scene-caption{top:9px;left:9px;font-size:8px;padding:6px 8px}.overlay{padding:8px}.intro-card{max-width:300px;padding:15px 19px 13px}.intro-santa{font-size:24px;margin:8px auto}.intro-card h2{font-size:25px}.intro-card p{font-size:10px;margin-bottom:10px}.play-button{height:38px}.intro-hint{margin-top:9px;font-size:7px}.controls-bar{height:56px;gap:8px}.tip-icon{width:25px;height:25px}.control-tip{gap:6px}.control-tip b,.wind b{font-size:8px}.control-tip small,.wind small{font-size:8px}.wind{gap:5px}.wind-icon{display:none}.wind-meter{gap:2px}.reload-button{margin-left:auto;padding:0 7px;height:31px;font-size:8px;gap:4px}.reload-button kbd{display:none}footer{height:25px;font-size:7px}.footer-right{display:none}}
@media(max-height:650px) and (min-width:601px){.topbar{height:58px}.game-layout{padding-top:12px;padding-bottom:8px}.left-panel{padding-top:7px}.side-panel h1{margin-top:12px;font-size:32px}.mission-copy{line-height:1.5}.objective-card{margin-top:14px}.hud-card{min-height:48px}.controls-bar{height:52px}.right-panel{gap:8px}.weather-card,.intel-card,.tip-card{padding:10px}}
@media(max-width:380px){.season-tag{display:none}.hud-card{padding:5px 6px}.hud-icon{font-size:12px}.ammo-card strong{font-size:7px}.weather-card{display:none}}

(() => {
  const canvas = document.getElementById('gameCanvas');
  const ctx = canvas.getContext('2d');
  const scene = document.getElementById('sceneWrap');
  const scoreEl = document.getElementById('score');
  const timerEl = document.getElementById('timer');
  const ammoEl = document.getElementById('ammo');
  const statusEl = document.getElementById('statusText');
  const toast = document.getElementById('toast');
  const startOverlay = document.getElementById('startOverlay');
  const endOverlay = document.getElementById('endOverlay');
  const soundButton = document.getElementById('soundButton');
  const reloadButton = document.getElementById('reloadButton');

  const state = {
    mode: 'intro', score: 0, ammo: 6, seconds: 45, lastFrame: 0,
    roundStart: 0, targetOffset: 0, hiddenUntil: 0, aim: { x: -1, y: -1 },
    snow: [], particles: [], sound: false, lastShot: 0, toastTimeout: 0,
    best: Number(localStorage.getItem('frosty-best') || 0),
  };
  document.getElementById('bestScore').textContent = String(state.best).padStart(2, '0');

  function resize() {
    const rect = scene.getBoundingClientRect();
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    canvas.width = Math.max(1, Math.round(rect.width * dpr));
    canvas.height = Math.max(1, Math.round(rect.height * dpr));
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    state.width = rect.width;
    state.height = rect.height;
    state.snow = Array.from({ length: Math.max(38, Math.floor(rect.width * rect.height / 7000)) }, () => ({
      x: Math.random() * rect.width, y: Math.random() * rect.height,
      r: .5 + Math.random() * 1.8, speed: 9 + Math.random() * 20, sway: Math.random() * 2,
      alpha: .2 + Math.random() * .52,
    }));
  }
  new ResizeObserver(resize).observe(scene);
  window.addEventListener('resize', resize);
  resize();

  const rand = (a, b) => a + Math.random() * (b - a);
  function roundedRect(x, y, w, h, r) {
    ctx.beginPath(); ctx.roundRect(x, y, w, h, r);
  }
  function drawMountain(x, base, width, peak, color) {
    ctx.beginPath(); ctx.moveTo(x, base); ctx.lineTo(x + width * .5, peak); ctx.lineTo(x + width, base); ctx.closePath(); ctx.fillStyle = color; ctx.fill();
    ctx.beginPath(); ctx.moveTo(x + width * .5, peak); ctx.lineTo(x + width * .67, peak + width * .15); ctx.lineTo(x + width * .55, peak + width * .12); ctx.lineTo(x + width * .45, peak + width * .17); ctx.closePath(); ctx.fillStyle = 'rgba(225,239,255,.62)'; ctx.fill();
  }
  function drawPine(x, ground, scale, color, snowColor) {
    ctx.fillStyle = '#182b3d'; ctx.fillRect(x - scale * .035, ground - scale * .18, scale * .07, scale * .2);
    for (let i = 0; i < 3; i++) {
      const top = ground - scale * (1.13 - i * .29), half = scale * (.3 - i * .055);
      ctx.beginPath(); ctx.moveTo(x, top); ctx.lineTo(x - half, top + scale * .43); ctx.lineTo(x + half, top + scale * .43); ctx.closePath(); ctx.fillStyle = color; ctx.fill();
      ctx.beginPath(); ctx.moveTo(x, top); ctx.lineTo(x - half * .64, top + scale * .25); ctx.lineTo(x - half * .1, top + scale * .21); ctx.lineTo(x + half * .08, top + scale * .31); ctx.closePath(); ctx.fillStyle = snowColor; ctx.globalAlpha = .85; ctx.fill(); ctx.globalAlpha = 1;
    }
  }
  function drawHouse(x, y, w, h, tone, style) {
    const roofH = h * .37;
    ctx.fillStyle = tone;
    ctx.fillRect(x, y + roofH, w, h - roofH);
    ctx.beginPath(); ctx.moveTo(x - w * .08, y + roofH); ctx.lineTo(x + w * .5, y); ctx.lineTo(x + w * 1.08, y + roofH); ctx.closePath(); ctx.fillStyle = style === 'red' ? '#774b52' : '#40566d'; ctx.fill();
    ctx.beginPath(); ctx.moveTo(x - w * .08, y + roofH); ctx.lineTo(x + w * .5, y); ctx.lineTo(x + w * 1.08, y + roofH); ctx.lineTo(x + w, y + roofH * .84); ctx.lineTo(x + w * .5, y + roofH * .13); ctx.lineTo(x, y + roofH * .86); ctx.closePath(); ctx.fillStyle = '#d7e8f4'; ctx.fill();
    ctx.fillStyle = '#f9d79c';
    const win = w * .15, wy = y + roofH + h * .18;
    ctx.fillRect(x + w * .17, wy, win, h * .17); ctx.fillRect(x + w * .68, wy, win, h * .17);
    ctx.fillStyle = 'rgba(255,235,184,.16)'; ctx.fillRect(x + w * .17 - 3, wy - 3, win + 6, h * .17 + 6); ctx.fillRect(x + w * .68 - 3, wy - 3, win + 6, h * .17 + 6);
    ctx.fillStyle = '#293c51'; ctx.fillRect(x + w * .44, y + roofH + h * .48, w * .18, h * .52);
    ctx.fillStyle = '#eef5fc'; ctx.fillRect(x + w * .05, y + roofH + h * .78, w * .9, h * .08);
    if (style === 'red') { ctx.strokeStyle = '#f2cc89'; ctx.lineWidth = Math.max(1, w * .012); ctx.beginPath(); ctx.moveTo(x + w * .11, y + roofH + 3); ctx.quadraticCurveTo(x + w * .5, y + roofH + h * .1, x + w * .9, y + roofH + 3); ctx.stroke(); }
  }
  function santaPosition(t) {
    const w = state.width, h = state.height;
    const direction = Math.sin(t * .22) > 0 ? 1 : -1;
    const x = w * (.08 + .84 * (0.5 + .5 * Math.sin(t * .22)));
    const y = h * (.77 + .012 * Math.sin(t * 1.9));
    const hidden = (x > w * .14 && x < w * .255) || (x > w * .50 && x < w * .62) || (x > w * .785 && x < w * .865);
    return { x, y, direction, hidden: hidden || (state.mode === 'playing' && performance.now() < state.hiddenUntil) };
  }
  function drawSanta(x, ground, direction, scale, t) {
    ctx.save(); ctx.translate(x, ground); ctx.scale(direction * scale, scale);
    const step = Math.sin(t * 8) * .045;
    // shadow
    ctx.fillStyle = 'rgba(17,34,48,.22)'; ctx.beginPath(); ctx.ellipse(0, .015, .18, .035, 0, 0, Math.PI * 2); ctx.fill();
    // legs and boots
    ctx.strokeStyle = '#26374b'; ctx.lineWidth = .075; ctx.lineCap = 'round';
    ctx.beginPath(); ctx.moveTo(-.035, -.22); ctx.lineTo(-.065 + step, -.04); ctx.moveTo(.04, -.22); ctx.lineTo(.085 - step, -.045); ctx.stroke();
    ctx.strokeStyle = '#262e3b'; ctx.lineWidth = .09; ctx.beginPath(); ctx.moveTo(-.065 + step, -.04); ctx.lineTo(-.015 + step, -.025); ctx.moveTo(.085 - step, -.045); ctx.lineTo(.13 - step, -.03); ctx.stroke();
    // coat body
    ctx.fillStyle = '#bc3f4a'; roundedRect(-.105, -.49, .21, .29, .065); ctx.fill();
    ctx.fillStyle = '#f4eee0'; roundedRect(-.11, -.255, .22, .05, .025); ctx.fill();
    ctx.beginPath(); ctx.moveTo(-.1, -.49); ctx.lineTo(-.14, -.34); ctx.lineTo(-.08, -.32); ctx.lineTo(-.04, -.43); ctx.closePath(); ctx.fillStyle = '#a93645'; ctx.fill();
    // belt
    ctx.fillStyle = '#333a46'; ctx.fillRect(-.103, -.34, .206, .035); ctx.fillStyle = '#f1c976'; ctx.fillRect(-.012, -.345, .035, .045);
    // arms
    ctx.strokeStyle = '#bd3f4a'; ctx.lineWidth = .075; ctx.lineCap = 'round';
    ctx.beginPath(); ctx.moveTo(-.08, -.445); ctx.lineTo(-.16, -.32 + step * .3); ctx.moveTo(.08, -.445); ctx.lineTo(.14, -.34 - step * .3); ctx.stroke();
    ctx.fillStyle = '#f0d7c3'; ctx.beginPath(); ctx.arc(-.16, -.32 + step * .3, .035, 0, Math.PI * 2); ctx.arc(.14, -.34 - step * .3, .035, 0, Math.PI * 2); ctx.fill();
    // head and beard
    ctx.fillStyle = '#efc6a9'; ctx.beginPath(); ctx.arc(0, -.54, .095, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#fff8e9'; ctx.beginPath(); ctx.moveTo(-.086, -.54); ctx.quadraticCurveTo(-.105, -.49, -.04, -.455); ctx.quadraticCurveTo(.065, -.45, .09, -.54); ctx.quadraticCurveTo(.04, -.505, 0, -.53); ctx.quadraticCurveTo(-.04, -.49, -.086, -.54); ctx.fill();
    ctx.fillStyle = '#5b3b38'; ctx.beginPath(); ctx.arc(.035, -.57, .009, 0, Math.PI * 2); ctx.fill();
    // hat
    ctx.fillStyle = '#c7424d'; ctx.beginPath(); ctx.moveTo(-.085, -.59); ctx.lineTo(-.055, -.72); ctx.quadraticCurveTo(.025, -.73, .09, -.6); ctx.closePath(); ctx.fill();
    ctx.fillStyle = '#fff5e8'; roundedRect(-.1, -.615, .205, .045, .02); ctx.fill();
    ctx.fillStyle = '#fff8ed'; ctx.beginPath(); ctx.arc(.03, -.73, .032, 0, Math.PI * 2); ctx.fill();
    // sack
    ctx.fillStyle = '#bd945d'; ctx.beginPath(); ctx.ellipse(-.18, -.43, .085, .12, -.18, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#dfbd81'; ctx.beginPath(); ctx.ellipse(-.2, -.47, .046, .022, -.3, 0, Math.PI * 2); ctx.fill();
    ctx.restore();
  }
  function drawScene(now) {
    const w = state.width, h = state.height;
    if (!w || !h) return;
    const time = now / 1000;
    const scale = Math.max(.72, Math.min(1.45, h / 420));
