  function drawReticle() {
    if (state.aim.x < 0 || state.mode !== 'playing') return;
    const { x, y } = state.aim;
    ctx.save(); ctx.translate(x,y); ctx.strokeStyle = 'rgba(234,248,255,.94)'; ctx.lineWidth = 1.25; ctx.shadowColor = 'rgba(0,0,0,.7)'; ctx.shadowBlur = 4;
